import{_ as i,l as n,o as e,c as l,v as r,p as s,x as o,d as p,i as d,S as u}from"./chunks/framework.InCnrqk-.js";const S=JSON.parse('{"title":"Quorum 读写","description":"","frontmatter":{"title":"Quorum 读写","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/quorum-rw.md","filePath":"cs/quorum-rw.md","lastUpdated":1789023840000}'),c={name:"cs/quorum-rw.md"};function m(h,a,f,_,A,B){const t=n("Mermaid");return e(),l("div",null,[a[1]||(a[1]=r('<h1 id="quorum-读写" tabindex="-1">Quorum 读写 <a class="header-anchor" href="#quorum-读写" aria-label="Permalink to &quot;Quorum 读写&quot;">​</a></h1><div class="epigraph"><p>写集与读集必须相交。相交点上带着足够新的时间戳，读就能拼出最近一次完成的写。</p><footer>—— 据 Gifford, Weighted Voting for Replicated Data, SOSP 1979；Attiya, Bar-Noy and Dolev, Sharing Memory Robustly in Message-Passing Systems, JACM 1995 整理</footer></div><p>上一课<a href="/cs/chain-replication">链式复制</a>用拓扑固定提交点。缺口是<strong>集合相交</strong>：不排成链，也能让每次读撞上每次写。本课钉 \\(R+W\\gt n\\)（及权重推广），不把 Dynamo 的 sloppy quorum 提前当默认。后课反熵处理「写没到齐」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(n\\) 个副本，写等 \\(W\\) 个 ack，读问 \\(R\\) 个，取时间戳最大者。若 \\(R+W\\gt n\\)，任一读集与任一写集共享至少一节点，该节点若保存了那次写，读就能看见。Attiya–Bar-Noy–Dolev（ABD）在异步崩溃下用两轮读/写给出线性一致寄存器：读也要再传播，防止旧值回写。</p><p>缺口：相交是安全的组合学；延迟是等最慢的那个法定人数成员。\\(W=n,R=1\\) 写最慢读最快；\\(W=1,R=n\\) 相反；\\(W=R=\\lfloor n/2\\rfloor+1\\) 对称。这是<a href="/cs/cap-pacelc">PACELC</a>无分区时的旋钮。</p><p><span class="marginnote">Gifford 加权投票：节点带票数，法定人数是票和，不是台数。ABD 说明消息传递上模拟共享内存要两轮。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>每值带单调时间戳（Lamport 钟或主序）。写：把新值送到 \\(W\\) 个。读：收 \\(R\\) 份，选最大时间戳；若要线性一致，把该值再写回 \\(W\\)（ABD 的 read-repair/传播）。时间戳不可比时不能只靠墙钟——接<a href="/cs/clock-drift">物理时钟</a>的 \\(\\varepsilon\\)。</p>',9)),(e(),s(u,null,{default:o(()=>[d(t,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20WSET%5B%22%E5%86%99%E9%9B%86%20%7CW%7C%22%5D%20--%3E%20INT%5B%22%E9%9D%9E%E7%A9%BA%E7%9B%B8%E4%BA%A4%22%5D%0A%20%20RSET%5B%22%E8%AF%BB%E9%9B%86%20%7CR%7C%22%5D%20--%3E%20INT%0A%20%20INT%20--%3E%20TS%5B%22%E6%9C%80%E5%A4%A7%E6%97%B6%E9%97%B4%E6%88%B3%22%5D%0A%20%20TS%20--%3E%20VAL%5B%22%E8%AF%BB%E5%80%BC%20%2F%20%E5%86%99%E5%9B%9E%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>分区：多数派只在一侧，另一侧 \\(W\\) 凑不齐则停写（CP）。若降低 \\(W\\) 使 \\(R+W\\le n\\)，相交消失，进入最终一致。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>Sloppy quorum（后课 Dynamo）：写进提示节点，相交暂时不成立，靠反熵补。那是故意放弃 ABD 安全换可用。严格 quorum 下，失败的写可能只到 \\(W-1\\)：读可能看见也可能看不见，线性一致要求把不确定的写当成未提交或用两阶段。工程上常用「写满 W 才 ack 客户端」，未 ack 的写以重试+幂等消化。</p><p>权重：慢盘少投票，SSD 多投票，仍要最坏相交。不要把权重当成负载均衡的充分条件。</p><p>本课不把 Raft 多数派日志当寄存器 quorum：共识是对<strong>操作序列</strong>的相交，寄存器是对<strong>单值</strong>的相交。后课 RSM 会接上。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 Merkle 树，不引入 LWW 细节。不把「三个九」当 \\(n=3\\) 的证明。后课默认：\\(R+W\\gt n\\) 加单调时间戳给崩溃异步寄存器；要可用性就放松相交并接受冲突。Dynamo 把放松做成系统。</p><p>相交是集合论，时间戳是打破平局的全序。缺一则读无「最近」。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>\\(R+W\\gt n\\)（或加权票和）保证读写集相交。</li><li>ABD：异步线性一致寄存器要读传播。</li><li>相交放松即放弃该寄存器的线性一致。</li><li>出处：Gifford, SOSP 1979；Attiya, Bar-Noy and Dolev, JACM 1995。</li></ul>',10))])}const D=i(c,[["render",m]]);export{S as __pageData,D as default};
